.netzhr-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #d7e0ec;
    background: radial-gradient(1200px 600px at 20% -10%, #15233f 0%, #0c1626 55%, #070d18 100%);
    border-radius: 18px;
}

.netzhr-container * {
    box-sizing: border-box;
}

.netzhr-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0e2a4a 0%, #123a63 50%, #0b6b6e 100%);
    color: #eaf4ff;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 16px 38px rgba(3, 10, 22, 0.55);
    border: 1px solid rgba(64, 224, 208, 0.18);
}

.netzhr-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.netzhr-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #7ff0dc;
    background: rgba(64, 224, 208, 0.10);
    border: 1px solid rgba(64, 224, 208, 0.36);
    padding: 5px 14px;
    border-radius: 999px;
}

.netzhr-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #c2d6ec;
}

.netzhr-firm {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.netzhr-firm-stat {
    flex: 1;
    background: #101e34;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 6px 18px rgba(3, 10, 22, 0.45);
    display: flex;
    flex-direction: column;
    gap: 4px;
    border-left: 4px solid #2bd4c0;
}

.netzhr-firm-num {
    font-weight: 800;
    font-size: 1.05rem;
    color: #7ff0dc;
    font-variant-numeric: tabular-nums;
}

.netzhr-firm-meta {
    font-size: 0.82rem;
    color: #8ea3c0;
    line-height: 1.4;
}

.netzhr-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #9fb3d1;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.netzhr-period-counter #currentDay,
.netzhr-period-counter #maxPeriods {
    font-weight: 800;
    color: #2bd4c0;
}

.netzhr-round-name {
    background: rgba(43, 212, 192, 0.14);
    color: #7ff0dc;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.netzhr-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffc875;
    background: rgba(255, 200, 117, 0.12);
    border: 1px solid rgba(255, 200, 117, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.netzhr-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.netzhr-status-card {
    background: #101e34;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 18px rgba(3, 10, 22, 0.45);
    border-top: 4px solid #2bd4c0;
    border-right: 1px solid rgba(120, 150, 190, 0.10);
}

.netzhr-card-kti { border-top-color: #2bd4c0; }
.netzhr-card-density { border-top-color: #4d9bff; }
.netzhr-card-concentration { border-top-color: #c98bff; }
.netzhr-card-retention { border-top-color: #ffc875; }

.netzhr-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8ea3c0;
}

.netzhr-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #eaf4ff;
    font-variant-numeric: tabular-nums;
}

.netzhr-card-kti .netzhr-value { color: #2bd4c0; }
.netzhr-card-density .netzhr-value { color: #4d9bff; }
.netzhr-card-concentration .netzhr-value { color: #c98bff; }
.netzhr-card-retention .netzhr-value { color: #ffc875; }

.netzhr-sublabel {
    font-size: 0.76rem;
    color: #7b8fac;
    line-height: 1.35;
}

.netzhr-card-kti.netzhr-kti-danger { border-top-color: #ff6b6b; }
.netzhr-card-kti.netzhr-kti-danger .netzhr-value { color: #ff6b6b; }
.netzhr-card-kti.netzhr-kti-good { border-top-color: #3ad29f; }
.netzhr-card-kti.netzhr-kti-good .netzhr-value { color: #3ad29f; }

.netzhr-card-concentration.netzhr-conc-danger { border-top-color: #ff6b6b; }
.netzhr-card-concentration.netzhr-conc-danger .netzhr-value { color: #ff6b6b; }
.netzhr-card-concentration.netzhr-conc-good { border-top-color: #3ad29f; }
.netzhr-card-concentration.netzhr-conc-good .netzhr-value { color: #3ad29f; }

.netzhr-card-retention.netzhr-ret-danger { border-top-color: #ff6b6b; }
.netzhr-card-retention.netzhr-ret-danger .netzhr-value { color: #ff6b6b; }
.netzhr-card-retention.netzhr-ret-good { border-top-color: #3ad29f; }
.netzhr-card-retention.netzhr-ret-good .netzhr-value { color: #3ad29f; }

.netzhr-resilience-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0e1a2e;
    border: 1px solid rgba(120, 150, 190, 0.16);
    color: #9fb3d1;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.netzhr-resilience-bar #resilienceDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #ff6b6b;
    font-weight: 800;
}

.netzhr-resilience-bar.netzhr-resilience-good #resilienceDisplay { color: #3ad29f; }
.netzhr-resilience-bar.netzhr-resilience-mid #resilienceDisplay { color: #ffc875; }

.netzhr-briefing {
    display: flex;
    gap: 14px;
    background: #101e34;
    border-left: 5px solid #2bd4c0;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(3, 10, 22, 0.40);
}

.netzhr-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.netzhr-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #eaf4ff;
    margin-bottom: 6px;
}

.netzhr-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #c2d6ec;
}

.netzhr-briefing-text strong { color: #7ff0dc; }
.netzhr-briefing-text em { color: #ffc875; font-style: italic; }

.netzhr-controls {
    background: #0e1a2e;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(3, 10, 22, 0.40);
    border: 1px solid rgba(120, 150, 190, 0.10);
}

.netzhr-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #eaf4ff;
    border-bottom: 2px solid rgba(120, 150, 190, 0.18);
    padding-bottom: 8px;
}

.netzhr-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #c2d6ec;
    margin: 14px 0 6px;
}

.netzhr-container select,
.netzhr-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2a3b58;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0a1424;
    color: #eaf4ff;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.netzhr-container select:focus,
.netzhr-container input[type="number"]:focus {
    outline: none;
    border-color: #2bd4c0;
    box-shadow: 0 0 0 3px rgba(43, 212, 192, 0.20);
}

.netzhr-container select option {
    background-color: #0a1424;
    color: #eaf4ff;
}

.netzhr-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2bd4c0;
}

.netzhr-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb3d1;
    margin-top: 4px;
}

.netzhr-range-readout span:nth-child(2) {
    color: #2bd4c0;
    font-weight: 800;
}

.netzhr-hint {
    font-size: 0.8rem;
    color: #7b8fac;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.netzhr-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.netzhr-container .btn-primary {
    background: linear-gradient(135deg, #0b6b6e 0%, #2bd4c0 100%);
    border: none;
    color: #062029;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(43, 212, 192, 0.28);
}

.netzhr-container .btn-primary:hover {
    filter: brightness(1.08);
}

.netzhr-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #2a3b58;
    color: #9fb3d1;
    background: transparent;
}

.netzhr-coach {
    background: linear-gradient(160deg, #0e2a4a 0%, #0b1c33 100%);
    color: #d7e6f5;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 22px rgba(3, 10, 22, 0.45);
    border: 1px solid rgba(64, 224, 208, 0.14);
}

.netzhr-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #7ff0dc;
    margin-bottom: 8px;
}

.netzhr-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.netzhr-coach-body strong { color: #7ff0dc; }
.netzhr-coach-body em { color: #ffc875; font-style: italic; }

.netzhr-history,
.netzhr-chart {
    background: #0e1a2e;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(3, 10, 22, 0.40);
    border: 1px solid rgba(120, 150, 190, 0.10);
}

.netzhr-history h3,
.netzhr-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #eaf4ff;
}

.netzhr-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #c2d6ec;
}

.netzhr-container table#usfHistoryTable th {
    background: #122441;
    color: #7ff0dc;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #1e3556;
}

.netzhr-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid rgba(120, 150, 190, 0.12);
    color: #c2d6ec;
}

.netzhr-container table#usfHistoryTable tr:nth-child(even) td {
    background: rgba(18, 36, 65, 0.45);
}

.netzhr-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .netzhr-container {
        padding: 14px;
    }
    .netzhr-header h1 {
        font-size: 1.7rem;
    }
    .netzhr-firm {
        flex-direction: column;
    }
    .netzhr-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .netzhr-value {
        font-size: 2rem;
    }
    .netzhr-clock {
        margin-left: 0;
    }
    .netzhr-period-counter {
        font-size: 0.88rem;
    }
    .netzhr-resilience-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .netzhr-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 FIX B - completion / board-debrief scorecard (append-only, namespaced) ===== */
.nh-cm { padding: 12px 6px; text-align: center; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; }
.nh-cm-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #8091a8; margin-bottom: 6px; }
.nh-cm-verdict { font-size: 22px; font-weight: 700; color: #edf1f7; margin-bottom: 8px; }
.nh-cm-score { font-size: 16px; color: #edf1f7; margin-bottom: 16px; }
.nh-cm-score strong { color: #34c6a8; }
.nh-cm-sub { font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: #8091a8; margin-bottom: 8px; }
.nh-cm-targets { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; margin-bottom: 16px; }
.nh-cm-target { display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border-radius: 20px; font-size: 13px; border: 1px solid transparent; }
.nh-cm-target.nh-cm-met { background: rgba(52,198,168,0.16); color: #79ddc7; border-color: rgba(52,198,168,0.4); }
.nh-cm-target.nh-cm-missed { background: rgba(255,112,112,0.14); color: #ff9d9d; border-color: rgba(255,112,112,0.36); }
.nh-cm-tick { font-weight: 700; }
.nh-cm-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.nh-cm-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 9px 13px; background: rgba(120,140,175,0.12); border-radius: 8px; min-width: 92px; }
.nh-cm-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #8091a8; }
.nh-cm-metric strong { font-size: 16px; color: #edf1f7; }
.nh-cm-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 720px; text-align: left; }
.nh-cm-insights li { padding: 9px 13px; margin-bottom: 7px; background: rgba(52,198,168,0.10); border-left: 3px solid #34c6a8; border-radius: 4px; color: #d9e4ef; font-size: 13px; line-height: 1.45; }
@media (max-width: 640px) { .nh-cm-metric { min-width: 70px; } .nh-cm-verdict { font-size: 19px; } }

