(function() {
    'use strict';

    class NetworkHRAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Network HR`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Triglav Systems d.o.o.).
            this.START_KTI = 41;          // knowledge-transfer index /100
            this.TARGET_KTI = 70;         // recovery target
            this.START_DENSITY = 0.06;    // cross-squad network density
            this.START_CONCENTRATION = 45;// % of cross-team ties through top connectors
            this.CONNECTORS = 2;          // remaining top connectors (both flight-risk)
            this.RETENTION_CAP = 240;     // €k targeted retention budget

            // Concept truths.
            this.TRUE_CHART = `network`;
            this.TRUE_CRITICAL = `concentration`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    kti: this.START_KTI,                 // knowledge-transfer index /100
                    density: this.START_DENSITY,         // cross-squad density
                    concentration: this.START_CONCENTRATION, // % ties through connectors
                    secured: 0,                          // connectors secured of 2
                    resilience: 18,                      // network resilience 0–100 (higher safer)
                    diagnosisDepth: 0,                   // how well the team read the ONA
                    bridgesBuilt: 0,                     // count of real relational bridges
                    headcountReflex: false,              // tried to hire away the problem
                    overInvested: false,                 // deepened the connectors (hero trap)
                    bridgedEverything: false,            // tried to close every hole at once
                    documentationFallacy: false,         // treated tacit as a wiki problem
                    ignoredRetention: false,             // never funded connector retention
                    siloManagers: false,                 // managers stayed inward
                    secondExitSurvived: false,           // R4 shock 1 absorbed
                    retentionSpent: 0,                    // €k committed to retention
                    ktiHistory: [this.START_KTI],
                    densityHistory: [this.START_DENSITY],
                    concentrationHistory: [this.START_CONCENTRATION],
                    resilienceHistory: [18],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    chart: `orgchart`,
                    critical: `lowpay`,
                    holes: `all`,
                    depth: 30,
                    connector: `hire`,
                    bridge: `wiki`,
                    lm: `supervise`,
                    budget: 20,
                    succession: `none`,
                    mobility: `zero`,
                    load: `protect`,
                    retention: 0,
                    shock: `scramble`,
                    mobilize: `hero`,
                    case: `reorg`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const ch = document.getElementById(`chartInput`);
                const cr = document.getElementById(`criticalInput`);
                const ho = document.getElementById(`holesInput`);
                const de = document.getElementById(`depthInput`);
                if (ch) decisions.chart = ch.value;
                if (cr) decisions.critical = cr.value;
                if (ho) decisions.holes = ho.value;
                if (de) decisions.depth = parseInt(de.value, 10);
                if (!Number.isFinite(decisions.depth) || decisions.depth < 0 || decisions.depth > 100) {
                    warn(`warn_depth_range`); return false;
                }
            } else if (round === 2) {
                const co = document.getElementById(`connectorInput`);
                const br = document.getElementById(`bridgeInput`);
                const lm = document.getElementById(`lmInput`);
                const bu = document.getElementById(`budgetInput`);
                if (co) decisions.connector = co.value;
                if (br) decisions.bridge = br.value;
                if (lm) decisions.lm = lm.value;
                if (bu) decisions.budget = parseInt(bu.value, 10);
                if (!Number.isFinite(decisions.budget) || decisions.budget < 0 || decisions.budget > 100) {
                    warn(`warn_budget_range`); return false;
                }
            } else if (round === 3) {
                const su = document.getElementById(`successionInput`);
                const mo = document.getElementById(`mobilityInput`);
                const lo = document.getElementById(`loadInput`);
                const re = document.getElementById(`retentionInput`);
                if (su) decisions.succession = su.value;
                if (mo) decisions.mobility = mo.value;
                if (lo) decisions.load = lo.value;
                if (re) decisions.retention = parseFloat(re.value);
                if (!Number.isFinite(decisions.retention) || decisions.retention < 0) {
                    warn(`warn_retention_value`); return false;
                }
            } else if (round === 4) {
                const sh = document.getElementById(`shockInput`);
                const mz = document.getElementById(`mobilizeInput`);
                const ca = document.getElementById(`caseInput`);
                const cv = document.getElementById(`convictionInput`);
                if (sh) decisions.shock = sh.value;
                if (mz) decisions.mobilize = mz.value;
                if (ca) decisions.case = ca.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas: KTI (/100), density (×100 scale internally), concentration (%, lower better),
            // resilience (/100, higher better).
            let ktiDelta = 0, densityDelta = 0, concentrationDelta = 0, resilienceDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: read the network (Common Error: managing by org chart).
                switch (d.chart) {
                    case `network`: ktiDelta += 3; resilienceDelta += 6; coachKey = `coach_r1_network`; break;
                    case `bothequal`: ktiDelta += 1; resilienceDelta += 1; coachKey = `coach_r1_bothequal`; break;
                    case `orgchart`: ktiDelta -= 2; resilienceDelta -= 2; coachKey = `coach_r1_orgchart`; break;
                }

                switch (d.critical) {
                    case `concentration`: resilienceDelta += 8; concentrationDelta -= 2; coachKey = `coach_r1_concentration`; break;
                    case `density`: resilienceDelta += 1; coachKey = `coach_r1_density`; break;
                    case `lowpay`: resilienceDelta -= 2; coachKey = `coach_r1_lowpay`; break;
                }

                switch (d.holes) {
                    case `targeted`: ktiDelta += 4; densityDelta += 1; resilienceDelta += 4; if (d.chart === `network` && d.critical === `concentration`) coachKey = `coach_r1_sharp`; break;
                    case `all`: resilienceDelta -= 2; ds.bridgedEverything = true; coachKey = `coach_r1_all`; break;
                    case `dense`: ktiDelta -= 2; coachKey = `coach_r1_dense`; break;
                }

                // Diagnostic depth on flight-risk: reading the overlay protects you later.
                ds.diagnosisDepth = d.depth;
                if (d.depth >= 60) { resilienceDelta += 4; }
                else if (d.depth <= 20) { resilienceDelta -= 3; }

                summaryKey = (d.chart === `network` && d.critical === `concentration` && d.holes === `targeted`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Plan: where to invest the network (Common Errors 1, 2, 6).
                const budget = d.budget / 100;

                switch (d.connector) {
                    case `deload`:
                        ktiDelta += 5; concentrationDelta -= 8; resilienceDelta += 9;
                        coachKey = `coach_r2_deload`;
                        break;
                    case `deepen`:
                        // Concentration trap (decision tree #2).
                        ds.overInvested = true;
                        ktiDelta += 3; concentrationDelta += 7; resilienceDelta -= 8;
                        coachKey = `coach_r2_deepen`;
                        break;
                    case `hire`:
                        // Headcount reflex (decision tree #1) — also breaches the cap.
                        ds.headcountReflex = true;
                        ktiDelta -= 4; concentrationDelta += 2; resilienceDelta -= 4;
                        coachKey = `coach_r2_hire`;
                        break;
                }

                switch (d.bridge) {
                    case `relational`:
                        ktiDelta += 7; densityDelta += 2; resilienceDelta += 7; ds.bridgesBuilt += 2;
                        // Bridges only land if you actually fund them.
                        if (budget < 0.25) { ktiDelta -= 4; densityDelta -= 1; ds.bridgesBuilt -= 1; coachKey = `coach_r2_underfunded`; }
                        else if (coachKey === `coach_r2_deload`) coachKey = `coach_r2_relational`;
                        break;
                    case `wiki`:
                        // Documentation fallacy (decision tree #4).
                        ds.documentationFallacy = true;
                        ktiDelta -= 2; resilienceDelta -= 2;
                        coachKey = `coach_r2_wiki`;
                        break;
                    case `reorg`:
                        // Concede the rigid reorg early — entrenches silos.
                        ktiDelta -= 5; densityDelta -= 1; resilienceDelta -= 3;
                        coachKey = `coach_r2_reorg`;
                        break;
                }

                switch (d.lm) {
                    case `enable`: ktiDelta += 4; densityDelta += 1; resilienceDelta += 4; break;
                    case `supervise`: ds.siloManagers = true; ktiDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r2_supervise` : coachKey; break;
                    case `ignore`: ds.siloManagers = true; ktiDelta -= 3; resilienceDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r2_lmignore` : coachKey; break;
                }

                summaryKey = (d.connector === `deload` && d.bridge === `relational` && d.lm === `enable`) ? `sum_r2_good` :
                             (d.connector === `hire` ? `sum_r2_headcount` :
                             (d.connector === `deepen` ? `sum_r2_concentration` :
                             (d.bridge === `wiki` ? `sum_r2_documentation` : `sum_r2_weak`)));
            } else if (round === 3) {
                // Decide: commit under the headcount cap (Common Errors 3 & 5).
                switch (d.succession) {
                    case `apprentice`: ktiDelta += 6; concentrationDelta -= 7; resilienceDelta += 9; ds.bridgesBuilt += 1; break;
                    case `document`: ds.documentationFallacy = true; ktiDelta += 1; resilienceDelta += 1; coachKey = `coach_r3_document`; break;
                    case `none`: resilienceDelta -= 3; coachKey = `coach_r3_nosuccession`; break;
                }

                switch (d.mobility) {
                    case `targeted`: ktiDelta += 6; densityDelta += 3; resilienceDelta += 6; ds.bridgesBuilt += 2; break;
                    case `flood`: ds.bridgedEverything = true; ktiDelta -= 3; densityDelta += 1; resilienceDelta -= 4; coachKey = `coach_r3_flood`; break;
                    case `zero`: ktiDelta -= 3; densityDelta -= 1; coachKey = `coach_r3_nomobility`; break;
                }

                switch (d.load) {
                    case `multipath`: concentrationDelta -= 10; resilienceDelta += 10; ktiDelta += 3; break;
                    case `newheroes`: ds.overInvested = true; concentrationDelta += 4; resilienceDelta -= 4; coachKey = `coach_r3_newheroes`; break;
                    case `protect`: concentrationDelta += 3; resilienceDelta -= 3; coachKey = `coach_r3_protect`; break;
                }

                // Retention & re-engagement for the flight-risk connectors (decision tree #5).
                ds.retentionSpent = Math.min(this.RETENTION_CAP, Math.round(ds.retentionSpent + d.retention));
                if (d.retention >= 240) { resilienceDelta += 7; concentrationDelta -= 2; }
                else if (d.retention <= 0) { ds.ignoredRetention = true; resilienceDelta -= 5; if (coachKey === `coach_default`) coachKey = `coach_r3_noretention`; }

                if (d.succession === `apprentice` && d.mobility === `targeted` && d.load === `multipath` && d.retention >= 240) {
                    coachKey = `coach_r3_resilient`;
                }

                summaryKey = (d.succession === `apprentice` && d.mobility === `targeted` && d.load === `multipath`) ? `sum_r3_good` :
                             (d.mobility === `flood` ? `sum_r3_flood` :
                             (d.load === `protect` || d.load === `newheroes` ? `sum_r3_concentration` : `sum_r3_weak`));
            } else if (round === 4) {
                // Recover: stress-test the network and defend the plan.
                // Shock 1 — second connector exit. Survival depends on resilience already built.
                switch (d.shock) {
                    case `bridges`:
                        if (ds.resilience >= 50 && ds.concentration <= 38) {
                            ds.secondExitSurvived = true;
                            ktiDelta += 6; resilienceDelta += 6; concentrationDelta -= 3; coachKey = `coach_r4_held`;
                        } else {
                            // Right answer, but the network wasn't actually rebuilt to back it.
                            ktiDelta -= 4; resilienceDelta -= 4; coachKey = `coach_r4_hollow`;
                        }
                        break;
                    case `reroute`: ds.overInvested = true; concentrationDelta += 8; resilienceDelta -= 8; ktiDelta -= 4; coachKey = `coach_r4_reroute`; break;
                    case `scramble`: ds.headcountReflex = true; ktiDelta -= 5; resilienceDelta -= 5; coachKey = `coach_r4_scramble`; break;
                }

                // Shock 2 — new strategic client demands rapid cross-squad mobilization.
                switch (d.mobilize) {
                    case `crossteam`:
                        if (ds.bridgesBuilt >= 3) { ktiDelta += 6; densityDelta += 2; resilienceDelta += 5; }
                        else { ktiDelta -= 2; coachKey = (coachKey === `coach_r4_held`) ? `coach_r4_nobridges` : coachKey; }
                        break;
                    case `hero`: ds.overInvested = true; concentrationDelta += 5; resilienceDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_hero` : coachKey; break;
                    case `decline`: ktiDelta -= 4; resilienceDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_decline` : coachKey; break;
                }

                // The 3-minute executive case.
                switch (d.case) {
                    case `kpis`: ktiDelta += 4; resilienceDelta += 4; if (d.shock === `bridges`) coachKey = (coachKey === `coach_r4_held`) ? `coach_r4_case` : coachKey; break;
                    case `busy`: resilienceDelta -= 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_busy` : coachKey; break;
                    case `reorg`: ktiDelta -= 5; resilienceDelta -= 5; coachKey = (coachKey === `coach_default`) ? `coach_r4_caseReorg` : coachKey; break;
                }

                if (d.conviction >= 60) { resilienceDelta += 3; }
                else if (d.conviction <= 25) { resilienceDelta -= 3; }

                summaryKey = (d.shock === `bridges` && ds.secondExitSurvived && d.mobilize === `crossteam` && d.case === `kpis`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas (clamped). density is tracked to 2 decimals. ----
            ds.kti = Math.max(0, Math.min(100, Math.round(ds.kti + ktiDelta)));
            ds.density = Math.max(0.02, Math.min(0.60, Math.round((ds.density + densityDelta * 0.03) * 100) / 100));
            ds.concentration = Math.max(8, Math.min(70, Math.round(ds.concentration + concentrationDelta)));
            ds.resilience = Math.max(0, Math.min(100, Math.round(ds.resilience + resilienceDelta)));

            // ---- Connectors secured is DERIVED: the remaining top connectors stay when
            // they are de-loaded (concentration falling), the network is resilient, and
            // retention is funded. Diagnostic depth in R1 sharpened the read. ----
            const deloadFactor = (70 - ds.concentration) / 62;            // 0..1 as concentration falls
            const resilienceFactor = ds.resilience / 100;                 // 0..1
            const moneyFactor = 0.55 + 0.45 * (ds.retentionSpent / this.RETENTION_CAP); // 0.55..1.0
            const readFactor = 0.85 + 0.15 * (ds.diagnosisDepth / 100);   // 0.85..1.0
            const keepShare = Math.max(0, Math.min(1,
                (0.45 * resilienceFactor + 0.55 * Math.max(0, deloadFactor)) * moneyFactor * readFactor
            ));
            ds.secured = Math.round(this.CONNECTORS * keepShare);

            ds.ktiHistory.push(ds.kti);
            ds.densityHistory.push(ds.density);
            ds.concentrationHistory.push(ds.concentration);
            ds.resilienceHistory.push(ds.resilience);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 FIX A - persist the composite where the gradebook / reporting layer reads it
            const _c = this._composite(ds);
            ds.score = _c;
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = _c;
            return {
                period: state.currentPeriod,
                score: _c,
                overallScore: _c,
                kti: ds.kti,
                ktiDelta: Math.round(ktiDelta),
                density: ds.density,
                concentration: ds.concentration,
                concentrationDelta: Math.round(concentrationDelta),
                resilience: ds.resilience,
                secured: ds.secured,
                retentionSpent: ds.retentionSpent,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _resilienceLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 60) return t(`resilience_strong`);
            if (v >= 35) return t(`resilience_mid`);
            return t(`resilience_fragile`);
        }

        _fmtDensity(v) {
            // Locale-aware two-decimal density: en "0.06", es "0,06".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(2);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`ktiDisplay`, `domainState.kti`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.netzhr-card-kti`);
                if (card) {
                    card.classList.toggle(`netzhr-kti-danger`, n < 45);
                    card.classList.toggle(`netzhr-kti-good`, n >= self.TARGET_KTI);
                }
                return `${n}`;
            });

            uiManager.bind(`densityDisplay`, `domainState.density`, (v) => self._fmtDensity(Number(v)));

            uiManager.bind(`concentrationDisplay`, `domainState.concentration`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.netzhr-card-concentration`);
                if (card) {
                    card.classList.toggle(`netzhr-conc-danger`, n >= 45);
                    card.classList.toggle(`netzhr-conc-good`, n <= 25);
                }
                return `${n}%`;
            });

            uiManager.bind(`retentionDisplay`, `domainState.secured`, (v) => {
                const r = Math.round(Number(v));
                const card = document.querySelector(`.netzhr-card-retention`);
                if (card) {
                    card.classList.toggle(`netzhr-ret-danger`, r < 1);
                    card.classList.toggle(`netzhr-ret-good`, r >= self.CONNECTORS);
                }
                return `${r} / ${self.CONNECTORS}`;
            });

            uiManager.bind(`resilienceDisplay`, `domainState.resilience`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.netzhr-resilience-bar`);
                if (bar) {
                    bar.classList.toggle(`netzhr-resilience-good`, n >= 60);
                    bar.classList.toggle(`netzhr-resilience-mid`, n >= 35 && n < 60);
                }
                return self._resilienceLabel(n);
            });

            // Depth slider readout.
            const de = document.getElementById(`depthInput`);
            const deReadout = document.getElementById(`depthReadout`);
            if (de && deReadout) {
                deReadout.textContent = de.value;
                de.addEventListener(`input`, function() { deReadout.textContent = de.value; });
            }

            // Budget slider readout.
            const bu = document.getElementById(`budgetInput`);
            const buReadout = document.getElementById(`budgetReadout`);
            if (bu && buReadout) {
                buReadout.textContent = bu.value;
                bu.addEventListener(`input`, function() { buReadout.textContent = bu.value; });
            }
        }

        getChartConfig() {
            return {
                networkChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: `Knowledge-transfer index (/100)`,
                                data: [],
                                borderColor: `#2bd4c0`,
                                backgroundColor: `rgba(43,212,192,0.14)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#2bd4c0`,
                                yAxisID: `y`
                            },
                            {
                                label: `Network density (×500)`,
                                data: [],
                                borderColor: `#4d9bff`,
                                backgroundColor: `rgba(77,155,255,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#4d9bff`,
                                yAxisID: `y`
                            },
                            {
                                label: `Connector concentration (%)`,
                                data: [],
                                borderColor: `#c98bff`,
                                backgroundColor: `rgba(201,139,255,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#c98bff`,
                                yAxisID: `y`
                            },
                            {
                                label: `Network resilience (/100)`,
                                data: [],
                                borderColor: `#ffc875`,
                                backgroundColor: `rgba(255,200,117,0.08)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#ffc875`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#9fb3d1`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#7b8fac` }, grid: { color: `rgba(120,150,190,0.10)` },
                                title: { display: true, text: `0–100`, color: `#7b8fac` }
                            },
                            x: {
                                ticks: { color: `#7b8fac` }, grid: { color: `rgba(120,150,190,0.06)` },
                                title: { display: true, text: `Round`, color: `#7b8fac` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.ktiHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Density is tiny (0.06..0.60) — scale ×500 to share the 0–100 axis, then cap.
            const densityScaled = ds.densityHistory.map((v) => Math.min(100, Math.round(v * 500)));
            return {
                networkChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.ktiHistory.map((v) => Math.round(v)) },
                        { data: densityScaled },
                        { data: ds.concentrationHistory.map((v) => Math.round(v)) },
                        { data: ds.resilienceHistory.map((v) => Math.round(v)) }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite formula (weights 0.34/0.22/0.14/0.15/0.15 sum to 1).
            const kti = Math.round(ds.kti);
            const density = Math.round(ds.density * 100) / 100;
            const concentration = Math.round(ds.concentration);
            const resilience = Math.round(ds.resilience);
            const secured = Math.round(ds.secured);
            const concScore = Math.max(0, (70 - concentration) / 62) * 100;
            const densityScore = Math.min(100, ((density - this.START_DENSITY) / (0.30 - this.START_DENSITY)) * 100);
            const securedScore = (secured / this.CONNECTORS) * 100;
            return Math.round(kti * 0.34 + concScore * 0.22 + Math.max(0, densityScore) * 0.14 + resilience * 0.15 + securedScore * 0.15);
        }

        formatCompletionMessage(summary) {
            // v1.1.0 FIX B - localized board-debrief scorecard (was: framework default that discarded
            // score, tier, targets and insights).
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            const score = (summary.composite != null) ? summary.composite : (summary.score != null ? summary.score : 0);
            const verdict = summary.gradeKey ? t(summary.gradeKey) : (summary.performance || '');
            const insights = summary.insights || [];
            const chip = function (ok, label) {
                return '<div class="nh-cm-target ' + (ok ? 'nh-cm-met' : 'nh-cm-missed') + '">'
                    + '<span class="nh-cm-tick">' + (ok ? '✓' : '✗') + '</span><span>' + label + '</span></div>';
            };
            const targets = ''
                + chip(!!summary.transferRecovered, t('tgt_transfer'))
                + chip(!!summary.deconcentrated, t('tgt_deconc'))
                + chip(!!summary.resilient, t('tgt_resilient'))
                + chip(!!summary.connectorsHeld, t('tgt_connectors'));
            const metric = function (label, val) {
                return '<div class="nh-cm-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            const densStr = (typeof this._fmtDensity === 'function' && summary.density != null) ? this._fmtDensity(summary.density) : (summary.density != null ? summary.density : '-');
            const conn = (this.CONNECTORS != null) ? this.CONNECTORS : 2;
            const metrics = ''
                + metric(t('kpi_kti'), (summary.kti != null ? summary.kti : '-') + '/100')
                + metric(t('kpi_density'), densStr)
                + metric(t('kpi_concentration'), (summary.concentration != null ? summary.concentration : '-') + '%')
                + metric(t('kpi_resilience'), (summary.resilience != null ? summary.resilience : '-') + '/100')
                + metric(t('kpi_secured'), (summary.secured != null ? summary.secured : '-') + '/' + conn);
            const items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="nh-cm">'
                +   '<div class="nh-cm-heading">' + t('comp_heading') + '</div>'
                +   '<div class="nh-cm-verdict">' + verdict + '</div>'
                +   '<div class="nh-cm-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   '<div class="nh-cm-sub">' + t('comp_targets_heading') + '</div>'
                +   '<div class="nh-cm-targets">' + targets + '</div>'
                +   '<div class="nh-cm-metrics">' + metrics + '</div>'
                +   (items ? '<ul class="nh-cm-insights">' + items + '</ul>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            const ds = window.mySimulation.state.domainState;
            const kti = Math.round(ds.kti);
            const density = Math.round(ds.density * 100) / 100;
            const concentration = Math.round(ds.concentration);
            const resilience = Math.round(ds.resilience);
            const secured = Math.round(ds.secured);

            // Composite: knowledge transfer, low concentration, density gain, resilience, connector retention.
            // v1.1.0 FIX A - delegated to _composite(ds) so the persisted per-round score and this
            // completion composite are identical by construction (verbatim v1.0.0 formula).
            const composite = this._composite(ds);

            const transferRecovered = kti >= this.TARGET_KTI;
            const deconcentrated = concentration <= 30;
            const denser = density >= 0.18;
            const resilient = resilience >= 60;
            const connectorsHeld = secured >= this.CONNECTORS;

            let pattern = `mixed`;
            if (ds.headcountReflex && !ds.bridgesBuilt) pattern = `headcount`;
            else if (ds.overInvested && concentration >= 45) pattern = `concentration`;
            else if (ds.documentationFallacy && kti < this.TARGET_KTI) pattern = `documentation`;
            else if (ds.bridgedEverything && resilience < 45) pattern = `overreach`;
            else if (transferRecovered && deconcentrated && resilient) pattern = `network`;

            // v1.1.0 FIX C - tier resolved to an i18n key and localized via t() (was hardcoded English).
            let perfKey = `grade_lost`;
            if (transferRecovered && deconcentrated && resilient && connectorsHeld && composite >= 72) perfKey = `grade_rebuilt`;
            else if (resilient && deconcentrated && pattern !== `concentration`) perfKey = `grade_resilience`;
            else if (ds.overInvested && concentration >= 45) perfKey = `grade_concentration`;
            else if (ds.headcountReflex && !connectorsHeld) perfKey = `grade_headcount`;
            else if (composite >= 52) perfKey = `grade_mixed`;
            const performance = t(perfKey);

            const insights = [];
            if (pattern === `network`) insights.push(window.mySimulation.t(`insight_network`));
            else if (pattern === `concentration`) insights.push(window.mySimulation.t(`insight_concentration`));
            else if (pattern === `headcount`) insights.push(window.mySimulation.t(`insight_headcount`));
            else if (pattern === `documentation`) insights.push(window.mySimulation.t(`insight_documentation`));
            else if (pattern === `overreach`) insights.push(window.mySimulation.t(`insight_overreach`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!connectorsHeld) insights.push(window.mySimulation.t(`insight_connectorlost`));
            if (ds.ignoredRetention) insights.push(window.mySimulation.t(`insight_retention`));
            if (ds.siloManagers) insights.push(window.mySimulation.t(`insight_managers`));
            if (!ds.secondExitSurvived && history.length >= 4) insights.push(window.mySimulation.t(`insight_shock`));
            if (transferRecovered && !resilient) insights.push(window.mySimulation.t(`insight_flowfragile`));

            return {
                gradeKey: perfKey,
                score: composite,
                kti: kti,
                density: density,
                concentration: concentration,
                resilience: resilience,
                secured: secured,
                transferRecovered: transferRecovered,
                deconcentrated: deconcentrated,
                denser: denser,
                resilient: resilient,
                connectorsHeld: connectorsHeld,
                pattern: pattern,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.headcountReflex) return window.mySimulation.t(`hint_headcount`);
            if (ds.concentration >= 50) return window.mySimulation.t(`hint_concentration`);
            if (ds.documentationFallacy && ds.kti < this.TARGET_KTI) return window.mySimulation.t(`hint_documentation`);
            if (ds.bridgedEverything && ds.resilience < 40) return window.mySimulation.t(`hint_overreach`);
            if (ds.ignoredRetention && state.currentPeriod >= 3) return window.mySimulation.t(`hint_retention`);
            if (ds.resilience < 30) return window.mySimulation.t(`hint_resilience`);
            if (ds.kti >= this.TARGET_KTI && ds.concentration <= 30 && ds.resilience >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.kti`, label: `Transfer`, i18nKey: `col_kti`, formatter: (v) => `${Math.round(v)}` },
